#!/usr/bin/env node
/**
 * Apex OS - Phase 4 employee-transitions surface verifier.
 *
 * The frontend has no unit runner, so the rules that keep these screens safe
 * are checked statically (the Playwright suite checks the runtime):
 *
 *  1. EVERY MUTATION CARRIES AN IDEMPOTENCY KEY generated by the caller, so a
 *     retry cannot duplicate an exit, transfer or settlement.
 *  2. NO GENERIC ERRORS FOR CODED REFUSALS: screens that mutate route errors
 *     through remediation.openFrom(err) before falling back to a toast.
 *  3. THE EMPLOYEE VIEW NEVER RENDERS NOTES, REFERENCES OR INVESTIGATION TEXT
 *     for F&F: the self branch uses the safe `reason`, not reasonCode/reference.
 *  4. THE ROUTES EXIST (transfer review, clearance, payroll, my resignation)
 *     and the user-detail composition happens at the route, not in platforms/.
 *  5. THE PAYROLL SCREEN SAYS THE UNRESOLVED DAYS WERE NOT COUNTED and sends an
 *     explicit acknowledgement; it never invents an outcome.
 *  6. COMPLIANCE ACTIONS NEVER OFFER SELF-APPROVAL: approve buttons are hidden
 *     when the viewer proposed or requested the item.
 *  7. NO RAW LINKS OR PERSONAL NAMES IN EVIDENCE REFERENCES: the input is
 *     upper-cased and described as an internal reference.
 *  8. TRANSITION ADMIN ROUTES STAY OUT OF THE MAIN SIDEBAR until the product
 *     team is ready to expose payroll, clearance and transfer review.
 */
import { readFileSync, existsSync } from 'node:fs';
import { join } from 'node:path';

const root = join(import.meta.dirname, '..', '..');
const read = (p) => readFileSync(join(root, p), 'utf8');
const problems = [];
const must = (cond, msg) => { if (!cond) problems.push(msg); };

const api = read('frontend/components/transitions/transitions-api.ts');
const exit = read('frontend/components/transitions/ExitPanel.tsx');
const transfer = read('frontend/components/transitions/TransferImpactModal.tsx');
const history = read('frontend/components/transitions/TransferHistory.tsx');
const compliance = read('frontend/components/transitions/ComplianceSettings.tsx');
const payroll = read('frontend/components/attendance/PayrollMonthClose.tsx');
const payrollApi = read('frontend/components/attendance/payroll-api.ts');
const sidebar = read('frontend/components/layout/sidebar.tsx');

// 1. Idempotency keys on every exit / transfer / clearance / F&F / retention / hold mutation.
const mutating = [...api.matchAll(/^\s+(\w+): \([^)]*\)[^=]*=>\s*r(?:<[^>]*>)?\(api\.(post|put|delete)\(/gm)].map((m) => m[1]);
const keyed = ['confirmTransfer', 'reconfirmTransfer', 'cancelTransfer', 'verifyProbation', 'startExit', 'adjustNotice', 'withdraw', 'updateClearance', 'releaseFnf', 'requestAdjustment', 'proposeRetention', 'requestHold'];
for (const name of keyed) {
  const line = api.split('\n').find((l) => new RegExp(`^\\s+${name}:`).test(l)) ?? '';
  const block = api.slice(api.indexOf(line), api.indexOf(line) + 600);
  must(/idempotencyKey/.test(block), `transitions-api: ${name} must send an idempotencyKey`);
}
must(mutating.length >= keyed.length, 'transitions-api: mutation scan found fewer calls than expected');
must(/newKey\(\)/.test(exit) && /newKey\(\)/.test(transfer), 'screens must generate keys with newKey()');
must(/useRef\(newKey\(\)\)/.test(transfer), 'TransferImpactModal must keep ONE key per submit attempt (useRef), reused on retry');

// 2. Remediation before toast.
for (const [name, src] of [['ExitPanel', exit], ['TransferImpactModal', transfer], ['TransferHistory', history], ['ComplianceSettings', compliance]]) {
  must(/remediation\.openFrom\(err\)/.test(src) || /a\.remediation\.openFrom|openFrom\(err\)/.test(src), `${name}: errors must go through remediation.openFrom(err)`);
  must(/RemediationDialog/.test(src), `${name}: must render RemediationDialog`);
}
must(!/Internal Server Error/i.test(exit + transfer + history + compliance), 'no generic Internal Server Error text');

// 3. Employee F&F view.
const selfBranch = exit.slice(exit.indexOf("mode === 'self' ? x.reason"), exit.indexOf("mode === 'self' ? x.reason") + 160);
must(/mode === 'self' \? x\.reason/.test(exit), 'employee F&F rows must show the safe reason, not the reason code');
must(/mode === 'staff' && x\.reference/.test(exit), 'F&F references are shown to staff only');
must(!/note/.test(selfBranch), 'employee F&F rows must not render notes');

// 4. Routes and composition.
for (const p of [
  'frontend/app/(dashboard)/(platform)/users/transfers/page.tsx',
  'frontend/app/(dashboard)/(platform)/users/clearance/page.tsx',
  'frontend/app/(dashboard)/attendance/payroll/page.tsx',
  'frontend/app/(dashboard)/profile/resignation/page.tsx',
]) must(existsSync(join(root, p)), `missing route ${p}`);
must(/UserTransitionsSection/.test(read('frontend/app/(dashboard)/(platform)/users/[id]/page.tsx')), 'user detail route must compose UserTransitionsSection');
must(!/components\/transitions/.test(read('platforms/core/users/administration/frontend/screens/UserDetailScreen.tsx')), 'platforms/** must not import frontend/**');
must(/Compliance/.test(read('frontend/components/settings/SettingsCenter.tsx')), 'Settings must expose the Compliance section');

// 5. Payroll.
must(/not counted as paid or unpaid/.test(payroll), 'payroll panel must state unresolved days were not counted as paid or unpaid');
must(/acknowledgeUnresolved/.test(payrollApi), 'finalizeMonth must send the acknowledgement fingerprint');
must(/Employment record review/.test(payroll), 'payroll must list employment-record review');

// 6. No self-approval offered.
must(/requestedById !== meId/.test(exit), 'F&F approve must be hidden from the requester');
must(/proposedById !== meId/.test(compliance), 'retention approve must be hidden from the proposer');
must(/requestedById !== meId/.test(compliance), 'legal-hold confirm must be hidden from the requester');

// 7. Evidence references.
must(/toUpperCase\(\)/.test(exit) && /AST-2026-0042/.test(exit), 'evidence input must be an upper-cased internal reference');

// 8. Phase 4 admin pages remain directly routable but are intentionally not
// advertised in the main navigation yet.
for (const href of ['/users/transfers', '/users/clearance', '/attendance/payroll']) {
  must(!sidebar.includes(`href: '${href}'`), `sidebar must not expose ${href}`);
}

if (problems.length) {
  console.error('Phase 4 surface verification FAILED:\n - ' + problems.join('\n - '));
  process.exit(1);
}
console.log('Phase 4 surface verification passed.');
